import { useState } from 'react'
import { Badge, Card, PageHeader } from '../../components/ui'
import type { SOF as SOFType } from '../../data/vendor'
import { useVendor } from '../../vendor/VendorContext'

function buildDocument(sof: SOFType): string {
  const line = '='.repeat(58)
  const rows = sof.events
    .map((e) => `${e.at.padEnd(18)}  ${e.remark}`)
    .join('\n')
  return [
    line,
    '          STATEMENT OF FACTS — BEACON Vendor Dock',
    line,
    `Reference : ${sof.ref}`,
    `Vessel    : ${sof.vessel}`,
    `Voyage    : ${sof.voyage}`,
    `Port/Berth: ${sof.port} / ${sof.berth}`,
    `Cargo     : ${sof.cargo}`,
    `Status    : ${sof.status.toUpperCase()}${sof.submittedAt ? ` (submitted ${sof.submittedAt})` : ''}`,
    line,
    'TIME (LT)           EVENT',
    '-'.repeat(58),
    rows || '(no events recorded)',
    line,
    'Generated by BEACON · the operating system for global port calls',
  ].join('\n')
}

export default function SOF() {
  const { sofs, createSOF, addSOFEvent, removeSOFEvent, submitSOF } = useVendor()
  const [activeId, setActiveId] = useState(sofs[0]?.id ?? '')
  const [showNew, setShowNew] = useState(false)
  const [preview, setPreview] = useState(false)

  const active = sofs.find((s) => s.id === activeId) ?? sofs[0]

  function download() {
    if (!active) return
    const blob = new Blob([buildDocument(active)], { type: 'text/plain' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `${active.ref}.txt`
    a.click()
    URL.revokeObjectURL(url)
  }

  return (
    <div className="stack">
      <PageHeader
        title="Statement of Facts"
        subtitle="Capture port events chronologically, generate the SOF document, and submit it to the record."
        action={
          <button className="btn btn-primary" onClick={() => setShowNew((v) => !v)}>
            + New SOF
          </button>
        }
      />

      {showNew && (
        <NewSOFForm
          onCreate={(input) => {
            const id = createSOF(input)
            setActiveId(id)
            setShowNew(false)
          }}
          onCancel={() => setShowNew(false)}
        />
      )}

      {!active && <Card className="empty">No statements yet — create one to start logging events.</Card>}

      {active && (
        <div className="da-shell">
          <div className="da-list">
            {sofs.map((s) => (
              <button
                key={s.id}
                className={`da-row${s.id === active.id ? ' active' : ''}`}
                onClick={() => setActiveId(s.id)}
              >
                <div className="da-row-top">
                  <strong className="mono">{s.ref}</strong>
                  <Badge label={s.status} />
                </div>
                <span className="mini-meta">
                  {s.vessel} · {s.port}
                </span>
                <span className="mini-meta">{s.events.length} events</span>
              </button>
            ))}
          </div>

          <Card className="da-detail">
            <div className="cd-head">
              <div>
                <h2 className="mono">{active.ref}</h2>
                <p className="muted-text">
                  {active.vessel} · {active.voyage} · {active.port} / {active.berth}
                </p>
              </div>
              <Badge label={active.status} />
            </div>

            <EventForm onAdd={(ev) => addSOFEvent(active.id, ev)} />

            <ol className="sof-timeline">
              {active.events.map((e) => (
                <li key={e.id}>
                  <span className="sof-time mono">{e.at}</span>
                  <span className="sof-remark">{e.remark}</span>
                  {active.status === 'draft' && (
                    <button className="icon-btn sof-del" onClick={() => removeSOFEvent(active.id, e.id)} aria-label="Remove">
                      ✕
                    </button>
                  )}
                </li>
              ))}
              {active.events.length === 0 && <li className="muted-text">No events recorded yet.</li>}
            </ol>

            <div className="cd-actions">
              <button className="btn btn-ghost" onClick={() => setPreview((v) => !v)}>
                {preview ? 'Hide preview' : '👁 Generate / preview'}
              </button>
              <button className="btn btn-ghost" onClick={download}>
                ⬇ Download .txt
              </button>
              {active.status === 'draft' ? (
                <button
                  className="btn btn-primary"
                  disabled={active.events.length === 0}
                  onClick={() => submitSOF(active.id)}
                >
                  Submit SOF
                </button>
              ) : (
                <span className="ok-tag">✓ Submitted {active.submittedAt}</span>
              )}
            </div>

            {preview && <pre className="sof-doc">{buildDocument(active)}</pre>}
          </Card>
        </div>
      )}
    </div>
  )
}

function EventForm({ onAdd }: { onAdd: (e: { at: string; remark: string }) => void }) {
  const [at, setAt] = useState('')
  const [remark, setRemark] = useState('')
  const valid = at && remark.trim()
  return (
    <div className="event-add">
      <input
        type="datetime-local"
        value={at}
        onChange={(e) => setAt(e.target.value)}
        aria-label="Event time"
      />
      <input
        placeholder="Event remark — e.g. Commenced loading"
        value={remark}
        onChange={(e) => setRemark(e.target.value)}
      />
      <button
        className="btn btn-primary btn-sm"
        disabled={!valid}
        onClick={() => {
          onAdd({ at: at.replace('T', ' '), remark: remark.trim() })
          setRemark('')
          setAt('')
        }}
      >
        + Log event
      </button>
    </div>
  )
}

function NewSOFForm({
  onCreate,
  onCancel,
}: {
  onCreate: (input: { ref: string; vessel: string; port: string; berth: string; voyage: string; cargo: string }) => void
  onCancel: () => void
}) {
  const [ref, setRef] = useState('')
  const [vessel, setVessel] = useState('')
  const [port, setPort] = useState('')
  const [berth, setBerth] = useState('')
  const [voyage, setVoyage] = useState('')
  const [cargo, setCargo] = useState('')
  const valid = ref.trim() && vessel.trim() && port.trim()
  return (
    <Card className="inline-form">
      <div className="form-grid">
        <label>
          SOF reference
          <input value={ref} onChange={(e) => setRef(e.target.value)} placeholder="SOF-2026-0020" />
        </label>
        <label>
          Vessel
          <input value={vessel} onChange={(e) => setVessel(e.target.value)} />
        </label>
        <label>
          Voyage
          <input value={voyage} onChange={(e) => setVoyage(e.target.value)} placeholder="V.215W" />
        </label>
        <label>
          Port
          <input value={port} onChange={(e) => setPort(e.target.value)} />
        </label>
        <label>
          Berth
          <input value={berth} onChange={(e) => setBerth(e.target.value)} />
        </label>
        <label>
          Cargo
          <input value={cargo} onChange={(e) => setCargo(e.target.value)} />
        </label>
      </div>
      <div className="modal-foot">
        <button className="btn btn-ghost" onClick={onCancel}>
          Cancel
        </button>
        <button
          className="btn btn-primary"
          disabled={!valid}
          onClick={() =>
            onCreate({
              ref: ref.trim(),
              vessel: vessel.trim(),
              port: port.trim(),
              berth: berth.trim() || '—',
              voyage: voyage.trim() || '—',
              cargo: cargo.trim() || '—',
            })
          }
        >
          Create SOF
        </button>
      </div>
    </Card>
  )
}
